from pathlib import Path
import json,html,re
from pptx import Presentation
from pptx.util import Inches,Pt
from pptx.dml.color import RGBColor
R=Path('public/reports/vinclub-roadmap');C=json.loads((R/'checks.json').read_text());e=html.escape
base=Path('public/reports/vinclub-final/index.html').read_text();css=base[base.index('<style>')+7:base.index('</style>')]
extra='''.comparison{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.phase-card{padding:20px;background:var(--paper);border-radius:28px;min-width:0}.phase-card h3{font-size:24px}.phase-card .screen{position:relative;width:100%;max-width:320px;margin:18px auto}.phase-card .screen>img{display:block;width:100%;height:auto;border-radius:20px}.annotation{position:absolute;left:0;right:0;border:2px solid var(--color-red-500);border-radius:14px;pointer-events:none}.annotation span{position:absolute;top:-11px;right:5px;background:var(--color-red-600);color:var(--paper);padding:2px 6px;font-size:9px;border-radius:4px;line-height:14px}.phase-card p{font-size:13px;color:var(--sub)}.mini-ia{display:flex;flex-direction:column;gap:6px;margin:14px 0}.mini-ia span{padding:8px 10px;background:var(--wash);border-radius:8px;font-size:12px}.mini-ia .added{background:var(--color-red-50);color:var(--color-red-800)}.phase-card .full{width:100%;height:auto;border-radius:14px}.phase-card details{padding:8px;background:var(--wash)}.cropped{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.cropped img{max-width:100%;max-height:440px;display:block;margin:16px auto;object-fit:contain}.cropped .card{min-width:0}.money{font-size:14px}.money td{font-size:13px}.hero-note{background:var(--color-yellow-50);padding:18px 22px;border-radius:14px;font-size:14px}.phase-card .link{margin-top:8px}@media(max-width:900px){.comparison,.cropped{grid-template-columns:1fr}.phase-card .screen{max-width:390px}}'''
phases=[('current','Hiện tại','Tài sản, hai sản phẩm tài chính, ưu đãi và trải nghiệm.',['Hội viên + Ví','Sinh lời / Vay nhanh','Quà + ưu đãi','Ảnh trải nghiệm'],[]),('feb','02/2027','Thêm lý do dùng quyền lợi và gói liên P&L; cân lại diện tích.',['Hội viên + Ví gọn hơn','MỚI · Quyền lợi đang chờ dùng','Tài chính chuyển sang hai card gọn','Quà + ưu đãi','MỚI · Gói hội viên liên P&L','Ảnh trải nghiệm'],['member-context','cross-pnl-bundle']),('end','Cuối 2027','Khám phá nhiều nhu cầu; nguồn cung và thời hạn cần chốt.',['Hội viên + Ví thu gọn','MỚI · Tìm dịch vụ theo nhu cầu','MỚI · Bốn nhóm dịch vụ','Hai sản phẩm tài chính','Quà + ưu đãi + gói','MỞ RỘNG · Sự kiện → Khám phá'],['ecosystem-search','cross-pnl-bundle'])]
cards=''
for key,title,desc,items,newblocks in phases:
 annotations=''
 for region in C['metrics'][key]:
  if region['id'] in newblocks and 0<=region['y']<844:
   top=region['y']/844*100;height=min(region['height'],844-region['y'])/844*100
   annotations+=f'<div class="annotation" style="top:{top:.3f}%;height:{height:.3f}%"><span>THÊM / BỐ TRÍ MỚI</span></div>'
 mini=''.join(f'<span class="{"added" if x.startswith(("MỚI","MỞ RỘNG")) else ""}">{e(x)}</span>' for x in items)
 cards+=f'<article class="phase-card"><span class="eyebrow">CẤU TRÚC HOME / {key.upper()}</span><h3>{title}</h3><p>{desc}</p><div class="screen"><img src="evidence/{key}-viewport.png" alt="UI {title}">{annotations}</div><a class="link {"primary" if key=="feb" else ""}" href="/vinclub-roadmap?phase={key}">Bấm thử {title} ↗</a><div class="mini-ia">{mini}</div><details><summary>Xem toàn bộ màn cuộn</summary><img class="full" src="evidence/{key}-unfolded.png" alt="Toàn bộ Home {title}"></details></article>'
count=sum(x['pass'] for x in C['checks'])
body=f'''<header><div class="container"><div class="eyebrow">VINCLUB / IA THEO BA MỐC / THAY ĐỔI TRÊN UI</div><h1>VinClub qua ba mốc phát triển.</h1><p class="lead">Giữ hệ visual của bạn, thay cách tổ chức chức năng theo phạm vi sản phẩm. Vùng đỏ là nội dung được thêm hoặc bố trí lại, không chỉ đổi nhãn.</p><div class="links"><a class="link primary" href="/vinclub-roadmap?phase=feb">Mở phương án 02/2027</a><a class="link" href="slides.html">Xem slide</a><a class="link" href="vinclub-roadmap.pptx">PowerPoint</a><a class="link" href="vinclub-roadmap.pdf">PDF</a></div></div></header><nav><div class="container"><a href="#compare">So ba UI</a><a href="#changes">Khác ở đâu?</a><a href="#tradeoff">Đánh đổi</a><a href="#money">Ra tiền</a><a href="#evidence">Kiểm chứng</a></div></nav><main class="container"><section id="compare"><div class="heading"><h2>So sánh cấu trúc và phần bổ sung.</h2></div><p class="hero-note">Phương án chính để kiểm chứng là <strong>02/2027</strong>. Cột cuối2027 là hướng mở rộng đề xuất theo B3, <strong>chưa phải cam kết triển khai</strong>. Bộ lọc dịch vụ dùng dữ liệu mẫu; không giả làm AI thật.</p><div class="comparison">{cards}</div></section><section id="changes"><div class="heading"><h2>Bốn thay đổi có chức năng và vị trí rõ.</h2></div><div class="cropped"><article class="card"><span class="badge new">02/2027 · THÊM VÀO ĐẦU VÙNG NỘI DUNG</span><h3>Quyền lợi đang chờ dùng</h3><img src="evidence/feb-member-context.png" alt="Block quyền lợi"><p><strong>Vì sao:</strong> B3 cần lịch sử / hạn điểm và phân phối quyền lợi. Khách thấy việc có thể làm với tài sản hiện hữu ngay khi mở Home.</p><p><strong>Bấm:</strong> mở Của tôi với điểm sắp hết hạn và voucher mẫu; tách khỏi rail đề nghị thương hiệu.</p><p><strong>Lấy chỗ từ đâu:</strong> giảm phần chừa ví và chuyển hai card tài chính sang cách xếp icon cạnh chữ. Không bỏ hai sản phẩm.</p></article><article class="card"><span class="badge new">02/2027 · THÊM SAU RAIL ƯU ĐÃI</span><h3>Gói riêng cho hội viên</h3><img src="evidence/feb-cross-pnl-bundle.png" alt="Block gói liên P&L"><p><strong>Vì sao:</strong> B3 mục3.3 có gói liên P&L. Đây là đề nghị kết hợp lưu trú / vui chơi, khác coupon một thương hiệu.</p><p><strong>Bấm:</strong> xem từng cấu phần, lưu gói quan tâm và tìm lại trong Của tôi. Không tự công bố giá hay giả lập đã mua.</p><p><strong>Giới hạn:</strong> cần đơn vị cung cấp, tồn, giá, sử dụng và đối soát trước khi bán thật.</p></article><article class="card"><span class="badge new">CUỐI 2027 · THÊM TRƯỚC HAI SẢN PHẨM</span><h3>Tìm nhu cầu + nhóm dịch vụ</h3><img src="evidence/end-ecosystem-search.png" alt="Tìm kiếm và danh mục"><p><strong>Vì sao:</strong> phạm vi thương mại rộng hơn ưu đãi và sự kiện. Khách có nhu cầu cụ thể cần tìm / chọn thay vì chỉ vuốt lời đề nghị.</p><p><strong>Bấm:</strong> lọc danh mục mẫu và đi đúng thương hiệu. Không gọi ô tìm kiếm là AI.</p><p><strong>Đánh đổi:</strong> nội dung khám phá lên trước tài chính; cần đo lại khả năng khách tìm sản phẩm tiền.</p></article><article class="card"><span class="badge new">CUỐI 2027 · MỞ RỘNG ĐIỀU HƯỚNG</span><h3>Sự kiện → Khám phá</h3><p><strong>Không đổi tên cho đẹp:</strong> màn đích mở rộng từ vé / sự kiện sang danh mục dịch vụ P&L, vẫn giữ sự kiện bên trong.</p><p><strong>Giữ:</strong> Trang chủ, Ưu đãi, QR và Hạng. Không thêm Chat khi SDK chưa có kế hoạch.</p><p><strong>Vòng đời chiến dịch:</strong> Tết2027 không kéo sang màn cuối2027. Có thể tái dùng nền chiến dịch theo B3 khi được triển khai.</p><a class="link" href="/vinclub-roadmap?phase=end">Kiểm tra điều hướng tương lai ↗</a></article></div></section><section id="tradeoff"><div class="heading"><h2>Đây là phương án tổ chức lại, chưa phải kết quả thắng UT.</h2></div><div class="three"><article class="card"><h3>Phạm vi hiện tại</h3><p>Home ưu tiên nhận diện tài sản và đề nghị có chọn lọc. Dễ nhìn nhưng khách phải tự tìm nơi dùng quyền lợi.</p></article><article class="card"><h3>Phạm vi tháng 2</h3><p>Quyền lợi có điểm vào riêng, tài chính gọn hơn, gói liên P&L được nhìn thấy. Đổi lại, ảnh trải nghiệm xuống thấp hơn.</p></article><article class="card"><h3>Phạm vi mở rộng</h3><p>Đáp ứng nhu cầu tìm dịch vụ rộng hơn. Đổi lại, Home nhiều lớp hơn và cần catalogue có chất lượng; không nên bật trước khi có nguồn cung.</p></article></div></section><section id="money"><div class="heading"><h2>Giá trị kinh doanh của phần thêm.</h2></div><div class="table-wrap"><table class="money"><thead><tr><th>Phần thay đổi</th><th>Khách được gì</th><th>Kinh tế</th><th>Điều kiện</th></tr></thead><tbody><tr><td>Quyền lợi chờ dùng</td><td>Biết điểm / voucher nào cần sử dụng</td><td>Đưa chi tiêu quay lại P&L; cần đo tăng thêm sau tài trợ</td><td>Nguồn quyền lợi, hạn, điều kiện và xác nhận sử dụng</td></tr><tr><td>Gói liên P&L</td><td>Nhiều nhu cầu trong một gói</td><td>Bán chéo và doanh số gói; phần VinClub theo thỏa thuận</td><td>Giá, tồn, cấu phần, hủy/hoàn, phân bổ doanh thu</td></tr><tr><td>Tìm / khám phá dịch vụ</td><td>Tìm đúng nơi đáp ứng nhu cầu</td><td>Giao dịch hoặc hoa hồng nếu có hợp tác; click chưa phải doanh thu</td><td>Catalogue, nguồn cung và attribution / kết quả đối tác</td></tr><tr><td>Hai sản phẩm tài chính giữ lại</td><td>Tìm hiểu tích lũy / tín dụng trong VinPay</td><td>Theo sản phẩm và hợp đồng tài chính; số dư / hạn mức không phải doanh thu</td><td>Điều khoản và đơn vị cung cấp, không tự đặt lãi/phí</td></tr></tbody></table></div></section><section id="evidence"><div class="heading"><h2>Đã bấm thử, không chỉ vẽ ảnh.</h2></div><article class="card"><p><strong>{count}/{len(C['checks'])} check đạt:</strong> ba cấu trúc khác nhau; quyền lợi mở đúng màn; gói lưu là quan tâm, không báo mua; tìm kiếm lọc và mở đúng thương hiệu; điều hướng tương lai khác; Tết cũ không kéo sang cuối2027; không tràn màn và không lỗi runtime.</p><p><strong>Chưa có:</strong> human UT, tích hợp production, hiệu quả kinh doanh hay lịch triển khai được duyệt cho toàn bộ cột cuối2027.</p><a href="checks.json">Log và vị trí block từng mốc ↗</a></article><div class="links"><a class="link primary" href="/vinclub-roadmap?phase=feb">Mở UI tháng 2</a><a class="link" href="/vinclub-roadmap?phase=end">Mở UI cuối2027</a><a class="link" href="../vinclub-final/index.html">Bản trước giữ lại</a></div></section></main><footer><div class="container">Các version trước được giữ nguyên. Mốc cuối2027 là đề xuất, không lấy hạn từ B3_ARCHIVED.<div class="indicator"></div></div></footer>'''
(R/'index.html').write_text('<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VinClub · Ba mốc IA với thay đổi nhìn thấy được</title><style>'+css+extra+'</style></head><body>'+body+'</body></html>')
raw=Path('app/globals.css').read_text();pal=dict(re.findall(r'--color-([\w-]+):\s*(#[0-9a-fA-F]+);',raw));prs=Presentation();prs.slide_width=Inches(13.333);prs.slide_height=Inches(7.5)
def rgb(x):return RGBColor.from_string(x.lstrip('#'))
def txt(sl,x,y,w,h,value,size=20,bold=False):
 tb=sl.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));tf=tb.text_frame;tf.word_wrap=True
 for i,line in enumerate(value.split('\n')):
  p=tf.paragraphs[0] if i==0 else tf.add_paragraph();p.text=line;p.font.name='Arial';p.font.size=Pt(size);p.font.bold=bold;p.font.color.rgb=rgb(pal['grey-900']);p.space_after=Pt(12)
htmlSlides=[]
slides=[('Hiện tại','Cấu trúc nguồn đang dùng.',['Tài sản → hai sản phẩm tài chính → quà / ưu đãi → trải nghiệm.','Chưa có vùng quyền lợi đang chờ và gói liên P&L trên Home.'],'current-viewport'),('02/2027','Thêm quyền lợi và gói; tổ chức lại diện tích.',['Quyền lợi lên đầu vùng nội dung.','Hai card tài chính chuyển cách xếp gọn hơn.','Thêm gói liên P&L trước trải nghiệm.'],'feb-viewport'),('Cuối2027','Thêm cơ chế tìm và khám phá nhu cầu.',['Tìm dịch vụ và bốn nhóm catalogue lên trước tài chính.','Sự kiện mở thành Khám phá; vẫn giữ tài chính và quyền lợi.','Đề xuất có điều kiện nguồn cung; không tự chốt hạn AI/Chat.'],'end-viewport'),('Quyền lợi chờ dùng','Khách biết mình có thể làm gì ngay.',['Điểm / voucher thật cần nguồn và điều kiện rõ.','Bấm dẫn tới khu vực sở hữu, không trộn vào rail đề nghị.'],'feb-member-context'),('Gói hội viên liên P&L','Một đề nghị cho nhiều nhu cầu.',['Nguồn B3 mục3.3; minh họa Vinpearl + VinWonders.','Xem cấu phần và lưu quan tâm; không tự đặt giá / báo đã mua.'],'feb-cross-pnl-bundle'),('Khám phá theo nhu cầu','Tăng độ phủ khi catalogue sẵn sàng.',['Ô tìm kiếm hiện lọc dữ liệu mẫu, không giả làm AI.','Điểm vào theo nhóm mở đúng thương hiệu.'],'end-ecosystem-search'),('Lấy chỗ ở đâu?','Mỗi phần thêm phải có đánh đổi.',['Tháng2: ví / card tài chính gọn hơn để có vùng quyền lợi.','Gói lên trước ảnh trải nghiệm: tăng cơ hội bán chéo, giảm ưu tiên cảm hứng.','Cuối2027: tìm dịch vụ lên trước tài chính; cần kiểm tra lại ưu tiên.'],None),('Chốt phương án để kiểm chứng','Tháng2 là bản chính; cuối2027 là hướng mở rộng.',['Giữ hình thức cũ, thay cách tổ chức theo phạm vi thật.',f'{count}/{len(C["checks"])} check tự động đạt; chưa có human UT.','Giao dịch, giá gói, ngân sách và nguồn cung cần xác nhận riêng.'],'feb-bundle-saved')]
for i,(title,take,bullets,file) in enumerate(slides,1):
 sl=prs.slides.add_slide(prs.slide_layouts[6]);sl.background.fill.solid();sl.background.fill.fore_color.rgb=rgb(pal['grey-50']);txt(sl,.5,.3,12,.3,f'VINCLUB / IA QUA BA MỐC / {i:02}',11,True);txt(sl,.5,.9,8.2,1,title,34,True);txt(sl,.5,2.1,8.2,1.1,take,22);txt(sl,.5,3.5,8.2,2.8,'\n'.join('• '+x for x in bullets),19)
 image=R/'evidence'/f'{file}.png' if file else None;pic=''
 if image and image.exists():
  from PIL import Image
  w,h=Image.open(image).size
  if h/w>1.5:sl.shapes.add_picture(str(image),Inches(9.6),Inches(.9),height=Inches(5.95))
  else:sl.shapes.add_picture(str(image),Inches(9),Inches(2.3),width=Inches(3.9))
  pic=f'<img src="evidence/{file}.png" alt="{e(title)}">'
 txt(sl,.5,7,12,.3,'Dữ liệu mẫu · Mốc tương lai là kế hoạch / đề xuất có điều kiện · Chưa chạy human UT',10)
 htmlSlides.append(f'<section class="slide"><div><small>VINCLUB / ROADMAP / {i:02}</small><h1>{e(title)}</h1><h2>{e(take)}</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in bullets)+f'</ul></div>{pic}<footer>Prototype, chưa kết nối giao dịch thật</footer></section>')
prs.save(R/'vinclub-roadmap.pptx')
oldslides=Path('public/reports/vinclub-final/slides.html').read_text();slidecss=oldslides[oldslides.index('<style>')+7:oldslides.index('</style>')]
(R/'slides.html').write_text('<!doctype html><html lang="vi"><meta charset="utf-8"><title>VinClub · Ba mốc khác nhau</title><style>'+slidecss+'</style><body>'+''.join(htmlSlides)+'<div class="controls">← → đổi slide · F trình chiếu · <a href="index.html">So ba màn</a></div><script>const ss=[...document.querySelectorAll(".slide")];let n=0;function show(){ss.forEach((s,i)=>s.classList.toggle("active",i===n))}document.addEventListener("keydown",e=>{if(e.key==="ArrowRight")n=Math.min(ss.length-1,n+1);if(e.key==="ArrowLeft")n=Math.max(0,n-1);if(e.key.toLowerCase()==="f")document.body.classList.toggle("present");show()});show()</script></body></html>')
print('Built real three-phase comparison, 8-slide deck and PPTX')
